"use client";

// coss ui Chat: composable chat primitives (messages, bubbles, reactions,
// replies, delivery states, typing indicator). Import from here or the parts.
export * from "./chat-coss-bubble";
export * from "./chat-coss-collapsible-message";
export * from "./chat-coss-conversation";
export * from "./chat-coss-date-pill";
export * from "./chat-coss-delivery-indicator";
export * from "./chat-coss-jump-to-latest-button";
export * from "./chat-coss-members";
export * from "./chat-coss-message-actions";
export * from "./chat-coss-message-bubble";
export * from "./chat-coss-message-info";
export * from "./chat-coss-message-layout";
export * from "./chat-coss-message-text";
export * from "./chat-coss-message";
export * from "./chat-coss-reaction-chip";
export * from "./chat-coss-reaction-picker";
export * from "./chat-coss-reply-preview";
export * from "./chat-coss-reply-reference";
export * from "./chat-coss-split-chat-message-preview";
export * from "./chat-coss-states";
export * from "./chat-coss-typing-indicator";
export * from "./chat-coss-unread-divider";
export * from "./chat-coss-use-chat-popup-dismissal";
export * from "./chat-coss-use-chat-scroll";

"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import type { ComponentProps, ReactElement } from "react";
import { cn } from "@/lib/utils";

export type ChatBubbleProps = useRender.ComponentProps<"div"> & {
  align?: "start" | "end";
  variant?: "default" | "muted";
  grouped?: boolean;
};

export function ChatBubble({
  align = "start",
  variant = "default",
  grouped = false,
  className,
  render,
  ...props
}: ChatBubbleProps): ReactElement {
  const defaultProps = {
    "data-slot": "chat-bubble",
    "data-align": align,
    "data-variant": variant,
    "data-grouped": grouped || undefined,
    className: cn(
      "relative flex min-w-0 flex-col gap-2 rounded-2xl px-3.5 py-2.5 text-foreground",
      variant === "default" ? "bg-foreground/12" : "bg-foreground/4",
      !grouped && (align === "end" ? "rounded-se-md" : "rounded-ss-md"),
      className,
    ),
  };

  return useRender({
    defaultTagName: "div",
    render,
    props: mergeProps<"div">(defaultProps, props),
  });
}

export function ChatBubbleReactions({
  className,
  ...props
}: ComponentProps<"div">): ReactElement {
  return (
    <div
      data-slot="chat-bubble-reactions"
      className={cn("flex flex-wrap gap-1 px-0.5", className)}
      {...props}
    />
  );
}

"use client";

import { ChevronDownIcon, ChevronUpIcon } from "lucide-react";
import type { ReactElement, ReactNode } from "react";
import { useState } from "react";
import { cn } from "@/lib/utils";
import {
  Collapsible,
  CollapsiblePanel,
  CollapsibleTrigger,
} from "./chat-coss-ui-collapsible";
import { splitChatMessagePreview } from "./chat-coss-split-chat-message-preview";

export type ChatCollapsibleMessageProps = {
  text: string;
  showMoreLabel: string;
  showLessLabel: string;
  side: "incoming" | "outgoing";
  maxPreviewLength?: number;
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  renderText?: (text: string) => ReactNode;
  className?: string;
};

function renderPlainText(text: string): ReactElement {
  return (
    <p className="m-0 whitespace-pre-wrap break-words text-sm leading-[1.55]">
      {text}
    </p>
  );
}

function ChatCollapsibleMessage({
  text,
  showMoreLabel,
  showLessLabel,
  side,
  maxPreviewLength,
  defaultOpen = false,
  open,
  onOpenChange,
  renderText = renderPlainText,
  className,
}: ChatCollapsibleMessageProps): ReactElement {
  const { preview, remainder } = splitChatMessagePreview(
    text,
    maxPreviewLength,
  );
  if (!remainder) {
    return <div className={cn("min-w-0", className)}>{renderText(text)}</div>;
  }

  return (
    <ExpandableChatMessage
      text={text}
      preview={preview}
      renderText={renderText}
      showMoreLabel={showMoreLabel}
      showLessLabel={showLessLabel}
      side={side}
      className={className}
      defaultOpen={defaultOpen}
      open={open}
      onOpenChange={onOpenChange}
    />
  );
}

function ExpandableChatMessage({
  text,
  preview,
  renderText,
  showMoreLabel,
  showLessLabel,
  side,
  className,
  defaultOpen,
  open: controlledOpen,
  onOpenChange,
}: {
  text: string;
  preview: string;
  renderText: (text: string) => ReactNode;
  showMoreLabel: string;
  showLessLabel: string;
  side: "incoming" | "outgoing";
  className?: string;
  defaultOpen: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}): ReactElement {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const open = controlledOpen ?? internalOpen;
  const setOpen = (nextOpen: boolean): void => {
    if (controlledOpen === undefined) setInternalOpen(nextOpen);
    onOpenChange?.(nextOpen);
  };
  const Icon = open ? ChevronUpIcon : ChevronDownIcon;

  return (
    <Collapsible
      open={open}
      onOpenChange={setOpen}
      className={cn("flex min-w-0 flex-col", className)}
    >
      <div className="grid">
        <div
          data-slot="chat-collapsible-preview"
          aria-hidden={open || undefined}
          className={cn(
            "mask-[linear-gradient(to_bottom,black_calc(100%-3rem),transparent)] col-start-1 row-start-1 self-start",
            open && "invisible",
          )}
        >
          {renderText(preview)}
        </div>
        <CollapsiblePanel className="col-start-1 row-start-1 min-w-0 motion-reduce:transition-none">
          <div
            aria-hidden={!open || undefined}
            className={open ? undefined : "invisible"}
          >
            {renderText(text)}
          </div>
        </CollapsiblePanel>
      </div>
      <CollapsibleTrigger
        type="button"
        className={cn(
          "mt-2 flex w-fit items-center gap-1 text-start text-xs outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring",
          side === "outgoing"
            ? "text-foreground/80 hover:text-foreground"
            : "text-muted-foreground hover:text-foreground",
        )}
      >
        {open ? showLessLabel : showMoreLabel}
        <Icon aria-hidden="true" className="size-3.5 shrink-0" />
      </CollapsibleTrigger>
    </Collapsible>
  );
}

export { ChatCollapsibleMessage, splitChatMessagePreview };

"use client";

import type { ComponentProps, ReactElement, ReactNode } from "react";
import { cn } from "@/lib/utils";
import {
  ScrollAreaPrimitive,
  ScrollBar,
} from "./chat-coss-ui-scroll-area";
import { ChatJumpToLatestButton } from "./chat-coss-jump-to-latest-button";
import type { ChatScrollController } from "./chat-coss-use-chat-scroll";

export type ChatConversationProps = ComponentProps<"div"> & {
  scroll: ChatScrollController;
  label: string;
  jumpLabel: ReactNode;
  contentClassName?: string;
  overlay?: ReactNode;
  inactive?: boolean;
  /** "off" when the caller announces arrivals itself, e.g. so paged-in history isn't read out. */
  live?: "polite" | "off";
};

export function ChatConversation({
  scroll,
  label,
  jumpLabel,
  contentClassName,
  children,
  overlay,
  inactive = false,
  live,
  className,
  ...props
}: ChatConversationProps): ReactElement {
  return (
    <div
      data-slot="chat-conversation"
      className={cn("relative isolate flex min-h-0 flex-1 flex-col", className)}
      {...props}
    >
      <ScrollAreaPrimitive.Root
        inert={inactive}
        className="size-full min-h-0 touch-auto before:pointer-events-none before:absolute before:inset-x-0 before:top-0 before:z-10 before:h-6 before:bg-linear-to-b before:from-popover before:to-transparent before:opacity-0 before:content-[''] after:pointer-events-none after:absolute after:inset-x-0 after:bottom-0 after:z-10 after:h-6 after:bg-linear-to-t after:from-popover after:to-transparent after:opacity-0 after:content-[''] data-overflow-y-end:after:opacity-100 data-overflow-y-start:before:opacity-100"
      >
        <ScrollAreaPrimitive.Viewport
          ref={scroll.viewportRef}
          role="log"
          aria-label={label}
          aria-live={live}
          aria-relevant="additions text"
          data-slot="scroll-area-viewport"
          className="h-full rounded-[inherit] outline-none transition-shadow focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset data-has-overflow-y:overscroll-y-contain data-has-overflow-x:overscroll-x-contain"
          onScroll={scroll.onScroll}
        >
          <ScrollAreaPrimitive.Content
            data-slot="scroll-area-content"
            className={cn("px-4 pb-4", contentClassName)}
            style={{ minWidth: 0 }}
          >
            {children}
          </ScrollAreaPrimitive.Content>
        </ScrollAreaPrimitive.Viewport>
        <ScrollBar orientation="vertical" />
        <ScrollBar orientation="horizontal" />
        <ScrollAreaPrimitive.Corner data-slot="scroll-area-corner" />
      </ScrollAreaPrimitive.Root>
      {scroll.showJump && !inactive && (
        <div className="pointer-events-none absolute inset-x-0 bottom-3 z-30 flex justify-center">
          <ChatJumpToLatestButton onClick={scroll.scrollToLatest}>
            {jumpLabel}
          </ChatJumpToLatestButton>
        </div>
      )}
      {overlay}
    </div>
  );
}

"use client";

import type { ComponentProps, ReactElement } from "react";
import { cn } from "@/lib/utils";

export function ChatDatePill({
  className,
  ...props
}: ComponentProps<"div">): ReactElement {
  return (
    <div
      data-slot="chat-date-pill"
      className={cn(
        "pointer-events-none sticky top-4 z-20 mx-auto flex h-6 w-fit items-center justify-center rounded-full border bg-popover/90 px-2 font-medium text-foreground text-xs backdrop-blur-xs",
        className,
      )}
      {...props}
    />
  );
}

"use client";

import {
  CheckCheckIcon,
  CheckIcon,
  CircleAlertIcon,
  ClockIcon,
} from "lucide-react";
import type { ReactElement } from "react";
import { cn } from "@/lib/utils";

export type ChatDeliveryIndicatorProps = {
  status: "sending" | "sent" | "delivered" | "read" | "failed";
  label: string;
};

export function ChatDeliveryIndicator({
  status,
  label,
}: ChatDeliveryIndicatorProps): ReactElement {
  const Icon = {
    sending: ClockIcon,
    sent: CheckIcon,
    delivered: CheckCheckIcon,
    read: CheckCheckIcon,
    failed: CircleAlertIcon,
  }[status];

  return (
    <span
      role="img"
      aria-label={label}
      title={label}
      data-slot="chat-delivery-indicator"
    >
      <Icon
        aria-hidden="true"
        className={cn(
          "size-3",
          status === "read" && "text-sky-600 dark:text-sky-400",
          status === "failed" && "text-destructive",
        )}
      />
    </span>
  );
}

"use client";

import { ArrowDownIcon } from "lucide-react";
import type { ReactElement, ReactNode } from "react";
import { cn } from "@/lib/utils";
import { Button, type ButtonProps } from "./chat-coss-ui-button";

export type ChatJumpToLatestButtonProps = Omit<
  ButtonProps,
  "children" | "size" | "variant"
> & {
  children: ReactNode;
};

export function ChatJumpToLatestButton({
  className,
  children,
  ...props
}: ChatJumpToLatestButtonProps): ReactElement {
  return (
    <div
      data-slot="chat-jump-to-latest"
      className="rounded-full bg-popover/90 backdrop-blur-xs"
    >
      <Button
        variant="outline"
        size="xs"
        className={cn(
          "pointer-events-auto gap-2 rounded-full before:rounded-full",
          className,
        )}
        {...props}
      >
        <ArrowDownIcon aria-hidden="true" />
        {children}
      </Button>
    </div>
  );
}

"use client";

import type { ComponentProps, ReactElement, ReactNode } from "react";
import { cn } from "@/lib/utils";

export type ChatMemberEntry = {
  id: string;
  name: ReactNode;
  avatar?: ReactNode;
  badges?: ReactNode;
  action?: ReactNode;
  dimmed?: boolean;
};

export type ChatMemberListProps = ComponentProps<"ul"> & {
  members: readonly ChatMemberEntry[];
};

export function ChatMemberList({
  members,
  className,
  ...props
}: ChatMemberListProps): ReactElement {
  return (
    <ul
      data-slot="chat-member-list"
      className={cn("m-0 flex list-none flex-col gap-2 p-0", className)}
      {...props}
    >
      {members.map((member) => (
        <li key={member.id} className="flex min-w-0 items-center gap-3">
          {member.avatar}
          <div className="flex min-w-0 flex-1 flex-wrap items-center gap-x-1.5 gap-y-1">
            <span
              className={cn(
                "truncate text-sm",
                member.dimmed ? "text-muted-foreground" : "font-medium",
              )}
            >
              {member.name}
            </span>
            {member.badges}
          </div>
          {member.action}
        </li>
      ))}
    </ul>
  );
}

export type ChatMemberSectionProps = ChatMemberListProps & {
  label: string;
  heading?: ReactNode;
};

export function ChatMemberSection({
  label,
  heading,
  members,
  ...props
}: ChatMemberSectionProps): ReactElement | null {
  if (!members.length) return null;
  return (
    <section aria-label={label} className="flex flex-col gap-4">
      {heading && (
        <h3 className="m-0 flex items-center gap-2 font-medium text-muted-foreground text-xs">
          {heading}
        </h3>
      )}
      <ChatMemberList members={members} {...props} />
    </section>
  );
}

"use client";

import { CornerDownLeftIcon, EllipsisIcon } from "lucide-react";
import type { ComponentProps, ReactElement, ReactNode, RefObject } from "react";
import { useRef, useState } from "react";
import { Button } from "./chat-coss-ui-button";
import { Menu, MenuPopup, MenuTrigger } from "./chat-coss-ui-menu";
import { Toolbar, ToolbarButton } from "./chat-coss-ui-toolbar";
import {
  Tooltip,
  TooltipPopup,
  TooltipTrigger,
} from "./chat-coss-ui-tooltip";
import { useChatPopupDismissal } from "./chat-coss-use-chat-popup-dismissal";

export type ChatMessageActionToolbarProps = {
  side: "incoming" | "outgoing";
  toolbarLabel: string;
  reactionPicker?: (toolbarRef: RefObject<HTMLDivElement | null>) => ReactNode;
  menuTriggerRef?: RefObject<HTMLButtonElement | null>;
  menuFinalFocus?: ComponentProps<typeof MenuPopup>["finalFocus"];
} & (
  | { onReply: () => void; replyLabel: string; replyTooltip: string }
  | { onReply?: never; replyLabel?: never; replyTooltip?: never }
) &
  (
    | { menuChildren: ReactNode; moreLabel: string; moreTooltip: string }
    | { menuChildren?: never; moreLabel?: never; moreTooltip?: never }
  );

export function ChatMessageActionToolbar({
  side,
  toolbarLabel,
  reactionPicker,
  replyLabel,
  replyTooltip,
  onReply,
  moreLabel,
  moreTooltip,
  menuChildren,
  menuTriggerRef: suppliedMenuTriggerRef,
  menuFinalFocus,
}: ChatMessageActionToolbarProps): ReactElement | null {
  const [menuOpen, setMenuOpen] = useState(false);
  const [menuDismissedOutside, setMenuDismissedOutside] = useState(false);
  const toolbarRef = useRef<HTMLDivElement>(null);
  const ownMenuTriggerRef = useRef<HTMLButtonElement>(null);
  const menuTriggerRef = suppliedMenuTriggerRef ?? ownMenuTriggerRef;

  useChatPopupDismissal(menuOpen, menuTriggerRef, () => setMenuOpen(false));

  if (!reactionPicker && !onReply && !menuChildren) return null;

  return (
    <Toolbar
      ref={toolbarRef}
      aria-label={toolbarLabel}
      data-slot="chat-message-action-toolbar"
      className="z-10 min-w-max flex-none items-center gap-0 self-center rounded-full bg-transparent p-0.5 opacity-0 pointer-coarse:opacity-100 transition-opacity group-hover/message:opacity-100 has-data-popup-open:opacity-100 has-focus-visible:opacity-100 motion-reduce:transition-none"
    >
      {reactionPicker?.(toolbarRef)}
      {onReply && (
        <Tooltip>
          <TooltipTrigger
            render={
              <ToolbarButton
                render={
                  <Button
                    size="icon-xs"
                    variant="ghost"
                    className="pointer-coarse:size-8 rounded-full before:rounded-full"
                    aria-label={replyLabel}
                    onMouseDown={(event) => {
                      if (event.button === 0) event.preventDefault();
                    }}
                    onClick={onReply}
                  />
                }
              />
            }
          >
            <CornerDownLeftIcon aria-hidden="true" />
          </TooltipTrigger>
          <TooltipPopup>{replyTooltip}</TooltipPopup>
        </Tooltip>
      )}
      {menuChildren && (
        <Menu
          open={menuOpen}
          onOpenChange={(open, details) => {
            setMenuDismissedOutside(
              details.reason === "outside-press" ||
                details.reason === "focus-out",
            );
            setMenuOpen(open);
          }}
        >
          <Tooltip>
            <TooltipTrigger
              render={
                <ToolbarButton
                  render={
                    <MenuTrigger
                      ref={menuTriggerRef}
                      render={
                        <Button
                          size="icon-xs"
                          variant="ghost"
                          className="pointer-coarse:size-8 rounded-full before:rounded-full"
                          aria-label={moreLabel}
                          data-message-actions=""
                        />
                      }
                    />
                  }
                />
              }
            >
              <EllipsisIcon aria-hidden="true" />
            </TooltipTrigger>
            <TooltipPopup>{moreTooltip}</TooltipPopup>
          </Tooltip>
          <MenuPopup
            anchor={toolbarRef}
            align={side === "outgoing" ? "start" : "end"}
            finalFocus={menuDismissedOutside ? false : menuFinalFocus}
          >
            {menuChildren}
          </MenuPopup>
        </Menu>
      )}
    </Toolbar>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ReactElement } from "react";
import { cn } from "@/lib/utils";
import { ChatBubble, type ChatBubbleProps } from "./chat-coss-bubble";

export type ChatMessageBubbleProps = Omit<
  ChatBubbleProps,
  "align" | "variant" | "grouped" | "render"
> & {
  side: "incoming" | "outgoing";
  firstInGroup?: boolean;
  animateEntrance?: boolean;
  highlighted?: boolean;
  onAnimationComplete?: () => void;
};

export function ChatMessageBubble({
  side,
  firstInGroup = true,
  animateEntrance = false,
  highlighted = false,
  children,
  className,
  onAnimationComplete,
  ...props
}: ChatMessageBubbleProps): ReactElement {
  const reduceMotion = useReducedMotion();
  const entranceOrigin =
    side === "outgoing"
      ? "origin-top-right rtl:origin-top-left"
      : "origin-top-left rtl:origin-top-right";
  return (
    <ChatBubble
      {...props}
      align={side === "outgoing" ? "end" : "start"}
      variant={side === "outgoing" ? "default" : "muted"}
      grouped={!firstInGroup}
      data-slot="chat-message-bubble"
      className={cn(highlighted ? "origin-center" : entranceOrigin, className)}
      render={
        <motion.div
          initial={
            animateEntrance && !reduceMotion
              ? { transform: "scale(0.92)" }
              : false
          }
          animate={highlighted && !reduceMotion ? "attention" : "rest"}
          variants={{
            rest: {
              transform: "scale(1)",
              transition: reduceMotion
                ? { duration: 0 }
                : { type: "spring", duration: 0.35, bounce: 0.45 },
            },
            attention: {
              transform: ["scale(1)", "scale(1.05)", "scale(1)"],
              transition: {
                duration: 0.42,
                times: [0, 0.28, 1],
                ease: [
                  [0.16, 1, 0.3, 1],
                  [0.34, 1.56, 0.64, 1],
                ],
              },
            },
          }}
          onAnimationComplete={onAnimationComplete}
        />
      }
    >
      {children}
      {highlighted && (
        <motion.div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 rounded-[inherit] ring-2 ring-foreground/25 ring-offset-2 ring-offset-background"
          initial={{ opacity: 0 }}
          animate={{ opacity: [0, 1, 0] }}
          transition={{ duration: 0.42, times: [0, 0.28, 1], ease: "easeOut" }}
        />
      )}
    </ChatBubble>
  );
}

"use client";

import type { ReactElement, ReactNode } from "react";
import { type ChatMemberEntry, ChatMemberSection } from "./chat-coss-members";
import { ChatMessageFooter } from "./chat-coss-message-layout";

export type ChatMessageInfoProps = {
  message: ReactNode;
  metadata: ReactNode;
  groups: readonly {
    id: string;
    label: string;
    icon?: ReactNode;
    members: readonly ChatMemberEntry[];
  }[];
};

export function ChatMessageInfo({
  message,
  metadata,
  groups,
}: ChatMessageInfoProps): ReactElement {
  return (
    <div data-slot="chat-message-info">
      <div className="mb-7 flex flex-col items-end gap-1">
        <div className="w-fit min-w-0 max-w-[83%]">{message}</div>
        <ChatMessageFooter>{metadata}</ChatMessageFooter>
      </div>
      <div className="flex flex-col gap-7">
        {groups.map((group) => (
          <ChatMemberSection
            key={group.id}
            label={group.label}
            heading={
              <>
                {group.icon}
                {group.label}
              </>
            }
            members={group.members}
          />
        ))}
      </div>
    </div>
  );
}

"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import type { ComponentProps, ReactElement } from "react";
import { cn } from "@/lib/utils";

export type ChatMessageLayoutProps = useRender.ComponentProps<"article"> & {
  align?: "start" | "end";
};

export function ChatMessageLayout({
  align = "start",
  className,
  render,
  ...props
}: ChatMessageLayoutProps): ReactElement {
  const defaultProps = {
    "data-slot": "chat-message",
    "data-align": align,
    className: cn(
      "group/message relative grid scroll-m-8 grid-cols-1 items-start rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-ring has-[>[data-slot=chat-message-avatar]]:grid-cols-[auto_minmax(0,1fr)] has-[>[data-slot=chat-message-avatar]]:gap-x-2 has-[>[data-slot=chat-message-header]]:gap-y-1",
      className,
    ),
  };

  return useRender({
    defaultTagName: "article",
    render,
    props: mergeProps<"article">(defaultProps, props),
  });
}

export function ChatMessageAvatar({
  className,
  ...props
}: ComponentProps<"div">): ReactElement {
  return (
    <div
      data-slot="chat-message-avatar"
      className={cn("col-start-1 row-start-2 w-7", className)}
      {...props}
    />
  );
}

export function ChatMessageHeader({
  className,
  ...props
}: ComponentProps<"div">): ReactElement {
  return (
    <div
      data-slot="chat-message-header"
      className={cn(
        "col-start-1 in-[[data-slot=chat-message]:has(>[data-slot=chat-message-avatar])]:col-start-2 row-start-1 px-1 font-medium text-muted-foreground text-xs group-data-[align=end]/message:justify-self-end",
        className,
      )}
      {...props}
    />
  );
}

export function ChatMessageContent({
  className,
  ...props
}: ComponentProps<"div">): ReactElement {
  return (
    <div
      data-slot="chat-message-content"
      className={cn(
        "col-start-1 in-[[data-slot=chat-message]:has(>[data-slot=chat-message-avatar])]:col-start-2 row-start-2 flex min-w-0 flex-col gap-1 group-data-[align=end]/message:items-end",
        className,
      )}
      {...props}
    />
  );
}

export function ChatMessageFooter({
  className,
  ...props
}: ComponentProps<"div">): ReactElement {
  return (
    <div
      data-slot="chat-message-footer"
      className={cn(
        "flex items-center gap-1.5 px-1 pt-0.5 text-[.625rem] text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

import type { ComponentProps, ReactElement } from "react";
import { cn } from "@/lib/utils";

export type ChatMessageTextProps = Omit<ComponentProps<"p">, "children"> & {
  text: string;
  mentions?: readonly string[];
};

export function ChatMessageText({
  text,
  mentions = [],
  className,
  ...props
}: ChatMessageTextProps): ReactElement {
  const names = new Set(mentions.map((name) => `@${name}`));
  const parts = text.split(/(@[\p{L}\p{N}_.-]+)/u);
  return (
    <p
      className={cn(
        "m-0 whitespace-pre-wrap break-words text-sm leading-[1.55]",
        className,
      )}
      {...props}
    >
      {parts.map((part, index) => {
        if (index > 0 && !/(?:^|\s)$/.test(parts[index - 1] ?? "")) return part;
        const mention = names.has(part) ? part : part.replace(/[.-]+$/, "");
        if (!names.has(mention)) return part;
        return (
          <span key={`${index}-${part}`}>
            <span className="font-medium">{mention}</span>
            {part.slice(mention.length)}
          </span>
        );
      })}
    </p>
  );
}

