      ref={triggerRef}
      render={
        <Button
          size="icon-xs"
          variant="ghost"
          className="pointer-coarse:size-8 rounded-full before:rounded-full"
          aria-label={triggerLabel}
          onMouseDown={(event) => {
            if (event.button === 0) event.preventDefault();
          }}
        />
      }
    />
