import { type RefObject, useEffect, useRef } from "react";

export function useChatPopupDismissal(
  active: boolean,
  triggerRef: RefObject<HTMLElement | null>,
  onDismiss: () => void,
): void {
  const onDismissRef = useRef(onDismiss);
  useEffect(() => {
    onDismissRef.current = onDismiss;
  }, [onDismiss]);

  useEffect(() => {
    const trigger = triggerRef.current;
    if (!active || !trigger) return;
    const ownerDocument = trigger.ownerDocument;
    const onScrollInput = (event: Event): void => {
      if (!(event.target instanceof Element)) return;
      if (event.target.closest('[role="menu"], [data-slot="popover-popup"]'))
        return;
      if (event instanceof KeyboardEvent) {
        if (
          event.defaultPrevented ||
          ![
            "ArrowUp",
            "ArrowDown",
            "ArrowLeft",
            "ArrowRight",
            "PageUp",
            "PageDown",
            "Home",
            "End",
            " ",
          ].includes(event.key) ||
          event.altKey ||
          event.ctrlKey ||
          event.metaKey ||
          event.target.closest(
            "input, textarea, select, button, a, [contenteditable], [role=menu], [role=listbox], [role=combobox], [role=slider], [role=tablist]",
          )
        )
          return;
      }
      const isScrollable = (element: Element): boolean => {
        const style = getComputedStyle(element);
        const page = element === ownerDocument.scrollingElement;
        return (
          (element.scrollHeight > element.clientHeight &&
            (page || /auto|scroll/.test(style.overflowY))) ||
          (element.scrollWidth > element.clientWidth &&
            (page || /auto|scroll/.test(style.overflowX)))
        );
      };
      // Dismiss on input in the scroller, never on automatic scrolling or menu navigation.
      for (
        let element: Element | null = event.target;
        element;
        element = element.parentElement
      ) {
        if (!isScrollable(element)) continue;
        if (element.contains(trigger)) onDismissRef.current();
        return;
      }
      // Modal menus intercept wheel/touch input with a backdrop over the scroller.
      const point =
        event instanceof WheelEvent
          ? event
          : event instanceof TouchEvent
            ? event.touches[0]
            : undefined;
      if (!point) return;
      for (
        let element = trigger.parentElement;
        element;
        element = element.parentElement
      ) {
        if (!isScrollable(element)) continue;
        const bounds = element.getBoundingClientRect();
        if (
          point.clientX >= bounds.left &&
          point.clientX <= bounds.right &&
          point.clientY >= bounds.top &&
          point.clientY <= bounds.bottom
        ) {
          onDismissRef.current();
          return;
        }
      }
    };
    const scrollInputs = ["wheel", "touchmove", "keydown"] as const;
    for (const type of scrollInputs)
      ownerDocument.addEventListener(type, onScrollInput, { passive: true });
    return () => {
      for (const type of scrollInputs)
        ownerDocument.removeEventListener(type, onScrollInput);
    };
  }, [active, triggerRef]);
}

"use client";

import {
  type UIEvent,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

export type ChatScrollOptions = {
  active?: boolean;
  paused?: boolean;
  itemCount: number;
  layoutKey?: string | number;
  onReachEnd?: () => void;
};

export function useChatScroll({
  active = true,
  paused = false,
  itemCount,
  layoutKey,
  onReachEnd,
}: ChatScrollOptions) {
  const viewportRef = useRef<HTMLDivElement>(null);
  const atBottomRef = useRef(true);
  const [showJump, setShowJump] = useState(false);

  // biome-ignore lint/correctness/useExhaustiveDependencies: Follow content changes before scroll events can misinterpret the new height.
  useLayoutEffect(() => {
    const viewport = viewportRef.current;
    if (!active || paused || !viewport) return;
    // Follow before a scroll event can interpret newly added height as scrolling away.
    if (atBottomRef.current) {
      viewport.scrollTop = viewport.scrollHeight;
      setShowJump(false);
    } else {
      setShowJump(
        viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight > 64,
      );
    }
  }, [active, paused, itemCount, layoutKey]);

  useEffect(() => {
    if (!active || paused) return;
    let observer: ResizeObserver | undefined;
    const frame = requestAnimationFrame(() => {
      const viewport = viewportRef.current;
      if (!viewport) return;
      observer = new ResizeObserver(() => {
        if (atBottomRef.current) viewport.scrollTop = viewport.scrollHeight;
      });
      observer.observe(viewport);
      if (viewport.firstElementChild)
        observer.observe(viewport.firstElementChild);
    });
    return () => {
      cancelAnimationFrame(frame);
      observer?.disconnect();
    };
  }, [active, paused]);

  const updatePosition = (): void => {
    const viewport = viewportRef.current;
    atBottomRef.current = Boolean(
      viewport &&
        viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight < 64,
    );
  };

  const onScroll = (_event: UIEvent<HTMLDivElement>): void => {
    if (paused) return;
    updatePosition();
    setShowJump(!atBottomRef.current);
    if (atBottomRef.current) onReachEnd?.();
  };

  const resetScroll = (atBottom = true): void => {
    atBottomRef.current = atBottom;
    setShowJump(!atBottom);
    requestAnimationFrame(() => {
      const viewport = viewportRef.current;
      if (viewport) viewport.scrollTop = atBottom ? viewport.scrollHeight : 0;
    });
  };

  const scrollToLatest = (): void => {
    atBottomRef.current = true;
    const viewport = viewportRef.current;
    viewport?.scrollTo({
      top: viewport.scrollHeight,
      behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches
        ? "auto"
        : "smooth",
    });
  };

  return {
    viewportRef,
    atBottomRef,
    showJump,
    onScroll,
    resetScroll,
    updatePosition,
    scrollToLatest,
  };
}

export type ChatScrollController = ReturnType<typeof useChatScroll>;
